import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import type { Note } from 'app/services/NotesService/types';

export const chordQualities = {
  major: { label: 'Мажор', suffix: '', intervals: [0, 4, 7], steps: [0, 2, 4] },
  minor: {
    label: 'Минор',
    suffix: 'm',
    intervals: [0, 3, 7],
    steps: [0, 2, 4],
  },
  diminished: {
    label: 'Уменьшённый',
    suffix: 'dim',
    intervals: [0, 3, 6],
    steps: [0, 2, 4],
  },
  augmented: {
    label: 'Увеличенный',
    suffix: 'aug',
    intervals: [0, 4, 8],
    steps: [0, 2, 4],
  },
  sus2: {
    label: 'Sus2',
    suffix: 'sus2',
    intervals: [0, 2, 7],
    steps: [0, 1, 4],
  },
  sus4: {
    label: 'Sus4',
    suffix: 'sus4',
    intervals: [0, 5, 7],
    steps: [0, 3, 4],
  },
  dominant7: {
    label: 'Доминантсептаккорд',
    suffix: '7',
    intervals: [0, 4, 7, 10],
    steps: [0, 2, 4, 6],
  },
  major7: {
    label: 'Большой мажорный септаккорд',
    suffix: 'maj7',
    intervals: [0, 4, 7, 11],
    steps: [0, 2, 4, 6],
  },
  minor7: {
    label: 'Малый минорный септаккорд',
    suffix: 'm7',
    intervals: [0, 3, 7, 10],
    steps: [0, 2, 4, 6],
  },
} as const;

export type ChordQuality = keyof typeof chordQualities;
export type KeyMode = 'major' | 'minor';
export type Chord = { root: string; quality: ChordQuality };
export type CircleKey = { major: string; minor: string; signature: string };

// Clockwise: ascending fifths. Each inner key shares the outer key's signature.
export const circleOfFifths: readonly CircleKey[] = [
  { major: 'C', minor: 'A', signature: 'Без знаков' },
  { major: 'G', minor: 'E', signature: '1 диез' },
  { major: 'D', minor: 'B', signature: '2 диеза' },
  { major: 'A', minor: 'F#', signature: '3 диеза' },
  { major: 'E', minor: 'C#', signature: '4 диеза' },
  { major: 'B', minor: 'G#', signature: '5 диезов' },
  { major: 'F#', minor: 'D#', signature: '6 диезов · также G♭ / E♭m' },
  { major: 'Db', minor: 'Bb', signature: '5 бемолей' },
  { major: 'Ab', minor: 'F', signature: '4 бемоля' },
  { major: 'Eb', minor: 'C', signature: '3 бемоля' },
  { major: 'Bb', minor: 'G', signature: '2 бемоля' },
  { major: 'F', minor: 'D', signature: '1 бемоль' },
];

const letters = ['C', 'D', 'E', 'F', 'G', 'A', 'B'];
const naturalPitches = [0, 2, 4, 5, 7, 9, 11];
const mod12 = (value: number) => ((value % 12) + 12) % 12;

export const formatPitch = (name: string) =>
  name.replace(/#/g, '♯').replace(/b/g, '♭');
export const chordSymbol = ({ root, quality }: Chord) =>
  `${formatPitch(root)}${chordQualities[quality].suffix}`;

const pitchOffset = (name: string) => {
  const letter = letters.indexOf(name[0]);
  if (letter < 0) throw new Error(`Unknown note: ${name}`);
  const accidentals =
    (name.match(/#/g) ?? []).length - (name.match(/b/g) ?? []).length;
  return naturalPitches[letter] + accidentals;
};

export const pitchClass = (name: string) => mod12(pitchOffset(name));

export const spellPitch = (
  root: string,
  interval: number,
  letterStep: number,
) => {
  const letter = (((letters.indexOf(root[0]) + letterStep) % 7) + 7) % 7;
  let accidental = mod12(pitchClass(root) + interval - naturalPitches[letter]);
  if (accidental > 6) accidental -= 12;
  return (
    letters[letter] +
    (accidental < 0 ? 'b'.repeat(-accidental) : '#'.repeat(accidental))
  );
};

export const chordTones = ({ root, quality }: Chord) => {
  const { intervals, steps } = chordQualities[quality];
  return intervals.map((interval, index) =>
    spellPitch(root, interval, steps[index]),
  );
};

export const chordVoicing = (
  chord: Chord,
  octave = 4,
  inversion = 0,
): Note[] => {
  const intervals = chordQualities[chord.quality].intervals;
  const turn = Math.max(
    0,
    Math.min(intervals.length - 1, Math.trunc(inversion)),
  );
  const base =
    Math.max(2, Math.min(5, Math.trunc(octave))) * 12 + pitchOffset(chord.root);
  const pitches = intervals.map(
    (interval, index) => base + interval + (index < turn ? 12 : 0),
  );
  return pitches
    .sort((a, b) => a - b)
    .map(
      pitch =>
        `${chromaticNotes[mod12(pitch)]}${Math.floor(pitch / 12)}` as Note,
    );
};

export const diatonicChords = (root: string, mode: KeyMode) => {
  const intervals =
    mode === 'major' ? [0, 2, 4, 5, 7, 9, 11] : [0, 2, 3, 5, 7, 8, 10];
  const qualities: ChordQuality[] =
    mode === 'major'
      ? ['major', 'minor', 'minor', 'major', 'major', 'minor', 'diminished']
      : ['minor', 'diminished', 'major', 'minor', 'minor', 'major', 'major'];
  const degrees =
    mode === 'major'
      ? ['I', 'ii', 'iii', 'IV', 'V', 'vi', 'vii°']
      : ['i', 'ii°', 'III', 'iv', 'v', 'VI', 'VII'];
  return intervals.map((interval, index) => ({
    root: spellPitch(root, interval, index),
    quality: qualities[index],
    degree: degrees[index],
  }));
};

// Exact pitch-class matches, independent of octave and doubling. Return all
// interpretations because sus and augmented chords can be ambiguous.
export const detectChords = (notes: readonly Note[]): Chord[] => {
  const pitches = Array.from(new Set(notes.map(pitchClass)));
  if (pitches.length < 3 || pitches.length > 4) return [];
  const bass = notes.slice().sort((a, b) => {
    const absolute = (note: Note) =>
      Number(note.slice(-1)) * 12 + pitchClass(note);
    return absolute(a) - absolute(b);
  })[0];
  const roots = [
    pitchClass(bass),
    ...pitches.filter(p => p !== pitchClass(bass)),
  ];
  return roots.flatMap(root =>
    (Object.keys(chordQualities) as ChordQuality[])
      .filter(quality => {
        const intervals: readonly number[] = chordQualities[quality].intervals;
        return (
          intervals.length === pitches.length &&
          intervals.every(interval => pitches.includes(mod12(root + interval)))
        );
      })
      .map(quality => ({ root: chromaticNotes[root], quality })),
  );
};
