type Pitch = { midi: number; strength: number };
export type FundamentalEvidence = {
  midi: number;
  frequency: number;
  amplitude: number;
};

// The inverse power spectrum measures how closely the signal repeats after
// one fundamental period. Normalize the Hann window's own autocorrelation so
// low notes are judged by the same criterion as high notes.
export const createMonophonicEvidence = (
  sampleRate: number,
  windowSize: number,
) => {
  let previous: FundamentalEvidence | undefined;
  const recentPower: number[] = [];
  let onsetFrames = 0;
  let polyphonicBase: number | undefined;
  const reset = () => {
    previous = undefined;
    recentPower.length = 0;
    onsetFrames = 0;
    polyphonicBase = undefined;
  };
  return {
    reset,
    filter(
      spectrum: Float32Array,
      fundamentals: FundamentalEvidence[],
      pitches: Pitch[],
    ): Pitch[] {
      let power = 0;
      let peak = 0;
      spectrum.forEach(value => {
        power += value * value;
        peak = Math.max(peak, value);
      });
      const prior =
        previous &&
        (fundamentals.find(candidate => candidate.midi === previous!.midi) ??
          previous);
      const candidates = prior
        ? [
            prior,
            ...fundamentals.filter(candidate => candidate.midi !== prior.midi),
          ]
        : fundamentals;
      const fundamental = candidates.find(candidate => {
        const known = candidate.midi === previous?.midi;
        if (!known && candidate.amplitude < Math.max(0.002, peak * 0.05))
          return false;
        const lag = sampleRate / candidate.frequency;
        let correlation = 0;
        for (let bin = 1; bin < spectrum.length; bin++) {
          correlation +=
            spectrum[bin] ** 2 *
            Math.cos((2 * Math.PI * bin * lag) / windowSize);
        }
        const windowCorrelation =
          (2 + Math.cos((2 * Math.PI * lag) / windowSize)) / 3;
        return (
          correlation / (power * windowCorrelation) >= (known ? 0.965 : 0.975)
        );
      });
      if (!fundamental) {
        reset();
        return pitches;
      }
      const same = previous?.midi === fundamental.midi;
      if (
        same &&
        recentPower.length === 3 &&
        power > recentPower[0] * 1.35 &&
        power > recentPower[2] * 1.08
      ) {
        // A fresh attack may introduce a real octave voice. Allow the ordinary
        // polyphonic fit to confirm it instead of locking a sustained solo.
        onsetFrames = 8;
      } else if (onsetFrames) onsetFrames--;
      const primary = pitches.find(pitch => pitch.midi === fundamental.midi);
      const amplitudeAt = (frequency: number) => {
        const bin = Math.round((frequency * windowSize) / sampleRate);
        return Math.max(
          spectrum[bin - 1] ?? 0,
          spectrum[bin] ?? 0,
          spectrum[bin + 1] ?? 0,
        );
      };
      const oddPartialsRemain = [1, 3, 5].some(
        harmonic =>
          amplitudeAt(fundamental.frequency * harmonic) >=
          Math.max(0.00015, peak * 0.015),
      );
      if (same && !oddPartialsRemain) {
        // Once the old voice's odd partials disappear, a real octave change
        // must be allowed even if the new note has the same overall level.
        reset();
        return pitches;
      }
      const balancedVoices = pitches.some(pitch => {
        if (
          pitch.midi === fundamental.midi ||
          pitch.strength <
            Math.max(0.008, primary?.strength ?? 0) *
              (onsetFrames || polyphonicBase === fundamental.midi ? 0.2 : 0.75)
        )
          return false;
        // An isolated strong third/fifth partial is still one voice. A real
        // additional voice needs its own partial series. Balanced octaves are
        // retained because their spectra inherently overlap the lower voice.
        if ((pitch.midi - fundamental.midi) % 12 === 0) return true;
        const evidence = fundamentals.find(
          candidate => candidate.midi === pitch.midi,
        );
        if (!evidence) return false;
        return [2, 3].every(
          harmonic =>
            amplitudeAt(evidence.frequency * harmonic) >=
            evidence.amplitude * 0.12,
        );
      });
      if (balancedVoices && !(same && !onsetFrames)) {
        reset();
        polyphonicBase = fundamental.midi;
        return pitches;
      }
      polyphonicBase = undefined;
      previous = fundamental;
      if (!same) recentPower.length = 0;
      recentPower.push(power);
      if (recentPower.length > 3) recentPower.shift();
      return [
        {
          midi: fundamental.midi,
          strength: Math.max(primary?.strength ?? 0, fundamental.amplitude),
        },
      ];
    },
  };
};
