export const POLY_SAMPLE_RATE = 12000;
export const POLY_WINDOW = 4096;

/** Iterative radix-2 FFT, with fixed storage reused for every audio frame. */
export const createSpectrum = (size = POLY_WINDOW) => {
  const real = new Float32Array(size);
  const imaginary = new Float32Array(size);
  const output = new Float32Array(size / 2);
  const window = Float32Array.from(
    { length: size },
    (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / size),
  );
  return (samples: Float32Array) => {
    let mean = 0;
    for (let i = 0; i < samples.length; i++) mean += samples[i];
    mean /= samples.length;
    let energy = 0;
    for (let i = 0; i < size; i++) {
      const value = samples[i] - mean;
      energy += value * value;
      real[i] = value * window[i];
      imaginary[i] = 0;
    }
    if (Math.sqrt(energy / size) < 0.006) {
      output.fill(0);
      return output;
    }
    for (let i = 1, reversed = 0; i < size; i++) {
      let bit = size >> 1;
      while (reversed & bit) {
        reversed ^= bit;
        bit >>= 1;
      }
      reversed ^= bit;
      if (i < reversed) {
        const value = real[i];
        real[i] = real[reversed];
        real[reversed] = value;
      }
    }
    for (let span = 2; span <= size; span <<= 1) {
      const angle = (-2 * Math.PI) / span;
      const wr = Math.cos(angle),
        wi = Math.sin(angle);
      for (let block = 0; block < size; block += span) {
        let r = 1,
          im = 0;
        for (let i = 0; i < span / 2; i++) {
          const a = block + i,
            b = a + span / 2;
          const tr = r * real[b] - im * imaginary[b];
          const ti = r * imaginary[b] + im * real[b];
          real[b] = real[a] - tr;
          imaginary[b] = imaginary[a] - ti;
          real[a] += tr;
          imaginary[a] += ti;
          const next = r * wr - im * wi;
          im = r * wi + im * wr;
          r = next;
        }
      }
    }
    for (let i = 0; i < output.length; i++)
      output[i] = (Math.hypot(real[i], imaginary[i]) * 4) / size;
    return output;
  };
};
