import type { Note } from 'app/services/NotesService/types';

import type { GuitarSamples } from './capture';
import { FAST_WINDOW, createFastPitchDetector } from './fastPitch';
import { createPitchOnsets } from './pitchOnsets';
import { createPolyphonicConfidence } from './polyphonicConfidence';
import {
  POLY_HOP,
  POLY_SAMPLE_RATE,
  POLY_WINDOW,
  PitchActivation,
  createPolyphonicPitchDetector,
} from './polyphonicPitch';
import type { RealtimeNote } from './realtime';

export type RealtimeFrame = {
  events: RealtimeNote[];
  soundingNotes: Note[];
  noteCount: number;
};
const names = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
const INTERVAL_WINDOW = 2048;
const noteName = (midi: number) =>
  `${names[midi % 12]}${Math.floor(midi / 12) - 1}` as Note;
const midiNumber = (note: Note) =>
  (Number(note.slice(-1)) + 1) * 12 + names.indexOf(note.slice(0, -1));
const isHarmonic = (midi: number, lower: number) => {
  if (midi <= lower) return false;
  const ratio = 2 ** ((midi - lower) / 12);
  return Math.abs(1200 * Math.log2(ratio / Math.round(ratio))) <= 18;
};

// Streaming low-pass/linear resampling keeps a single sample clock across
// arbitrary device blocks, including 44.1 and 96 kHz inputs.
const lowPass = (rate: number, q: number) => {
  const w = (2 * Math.PI * Math.min(4800, rate * 0.4)) / rate;
  const alpha = Math.sin(w) / (2 * q),
    a0 = 1 + alpha;
  const b0 = (1 - Math.cos(w)) / 2 / a0,
    b1 = 2 * b0;
  const a1 = (-2 * Math.cos(w)) / a0,
    a2 = (1 - alpha) / a0;
  let x1 = 0,
    x2 = 0,
    y1 = 0,
    y2 = 0;
  return (x: number) => {
    const y = b0 * x + b1 * x1 + b0 * x2 - a1 * y1 - a2 * y2;
    x2 = x1;
    x1 = x;
    y2 = y1;
    y1 = y;
    return y;
  };
};

export const createPolyphonicStream = (
  onFrame: (frame: RealtimeFrame) => void,
) => {
  const detect = createPolyphonicPitchDetector();
  const interval = createPolyphonicPitchDetector(INTERVAL_WINDOW);
  const fast = createFastPitchDetector(POLY_SAMPLE_RATE);
  const confidence = createPolyphonicConfidence();
  const onsets = createPitchOnsets();
  const ring = new Float32Array(POLY_WINDOW);
  const window = new Float32Array(POLY_WINDOW);
  const active = new Map<
    Note,
    {
      id: number;
      start: number;
      end: number;
      pending?: number;
      missing?: number;
      missingFrames: number;
    }
  >();
  const candidates = new Map<
    Note,
    { start: number; frames: number; observedAt: number }
  >();
  const released = new Map<Note, { id: number; start: number; end: number }>();
  let rate = 0,
    epoch = 0,
    received = 0,
    generated = 0,
    nextSample = 0,
    previous = 0;
  let filter1 = (x: number) => x,
    filter2 = (x: number) => x;
  let nextId = 0,
    finished = false,
    hopEnergy = 0,
    silentHops = 0;
  let soundStart: number | undefined;
  let quietStart: number | undefined;
  let sounding = false;
  let monoPitch: number | undefined;
  let monoSeen = -Infinity;
  let monoChanged = -Infinity;
  const levels: number[] = [];
  let attack = -Infinity;
  const filterHarmonics = (
    pitches: PitchActivation[],
    independentAttack: boolean,
  ) =>
    pitches.filter(pitch => {
      if (active.has(noteName(pitch.midi))) return true;
      return !pitches.some(lower => {
        if (lower.midi >= pitch.midi || pitch.strength >= lower.strength * 0.8)
          return false;
        if (!isHarmonic(pitch.midi, lower.midi)) return false;
        const voice = active.get(noteName(lower.midi));
        return !(independentAttack && voice && voice.start < attack - 160);
      });
    });
  const event = (
    note: Note,
    voice: { id: number; start: number; end: number },
  ): RealtimeNote => ({
    id: voice.id,
    startedAt: epoch,
    note: {
      note,
      start: voice.start,
      duration: Math.max(1, voice.end - voice.start),
    },
  });
  const update = (
    notes: Note[],
    center: number,
    end: number,
    silence?: number,
    confirmationFrames = 2,
    cautious: Note[] = [],
    onsetAge = 640,
  ) => {
    const events: RealtimeNote[] = [];
    const wasEmpty = !active.size;
    const onsetFor = (note: Note) => {
      const onset = onsets.get(midiNumber(note), end);
      return onset && end - onset.time <= onsetAge ? onset : undefined;
    };
    active.forEach((voice, note) => {
      if (notes.includes(note)) {
        const onset = onsetFor(note);
        if (
          onset?.independent &&
          onset.time > voice.start + 160 &&
          onset.time < end
        ) {
          voice.pending ??= onset.time;
        }
        // The long fit can still describe the previous pick. Keep the attack
        // until its time center catches up; discard it if this voice ends.
        if (voice.pending !== undefined && voice.pending <= center) {
          voice.end = voice.pending;
          events.push(event(note, voice));
          voice.id = ++nextId;
          voice.start = voice.pending;
          voice.pending = undefined;
        }
        voice.missing = undefined;
        voice.missingFrames = 0;
        voice.end = end;
        events.push(event(note, voice));
      } else {
        voice.missing ??= silence ?? center;
        voice.missingFrames++;
        if (silence !== undefined || voice.missingFrames >= 2) {
          voice.end = Math.max(voice.start + 1, voice.missing ?? center);
          events.push(event(note, voice));
          released.set(note, {
            id: voice.id,
            start: voice.start,
            end: voice.end,
          });
          active.delete(note);
        }
      }
    });
    candidates.forEach((_, note) => {
      if (!notes.includes(note)) candidates.delete(note);
    });
    notes.forEach(note => {
      if (active.has(note)) return;
      const recentOnset =
        wasEmpty &&
        soundStart !== undefined &&
        soundStart >=
          end - ((POLY_WINDOW + POLY_HOP) / POLY_SAMPLE_RATE) * 1000;
      const onset = onsetFor(note);
      const start = onset
        ? Math.max(soundStart ?? 0, onset.time)
        : recentOnset
        ? soundStart!
        : center;
      const candidate = candidates.get(note) ?? {
        start,
        frames: 0,
        observedAt: center,
      };
      candidate.frames++;
      candidates.set(note, candidate);
      if (
        candidate.frames <
        (cautious.includes(note)
          ? Math.max(5, confirmationFrames)
          : confirmationFrames)
      )
        return;
      // A brief disagreement between the two window lengths must not record
      // the same measured attack twice. A distinct attack still gets a new ID.
      const prior = released.get(note);
      const resume =
        prior &&
        prior.start === candidate.start &&
        candidate.observedAt - prior.end <= 160;
      const voice = {
        id: resume ? prior.id : ++nextId,
        start: candidate.start,
        end,
        missingFrames: 0,
      };
      active.set(note, voice);
      released.delete(note);
      candidates.delete(note);
      events.push(event(note, voice));
    });
    onFrame({
      events,
      soundingNotes: Array.from(active.keys()),
      noteCount: nextId,
    });
  };
  const append = (sample: number) => {
    ring[generated % POLY_WINDOW] = sample;
    generated++;
    hopEnergy += sample * sample;
    if (generated % POLY_HOP === 0) {
      const quiet = Math.sqrt(hopEnergy / POLY_HOP) < 0.006;
      hopEnergy = 0;
      const start = ((generated - POLY_HOP) / POLY_SAMPLE_RATE) * 1000;
      if (quiet) {
        quietStart ??= start;
        silentHops++;
        if (silentHops >= 2 && sounding) {
          sounding = false;
          detect.reset();
          interval.reset();
          fast.reset();
          confidence.reset();
          onsets.reset();
          released.clear();
          monoPitch = undefined;
          monoSeen = monoChanged = -Infinity;
          levels.length = 0;
          attack = -Infinity;
          update([], start, start, quietStart);
        }
      } else {
        if (!sounding) soundStart = start;
        sounding = true;
        silentHops = 0;
        quietStart = undefined;
      }
    }
    if (generated % POLY_HOP !== 0 || !sounding) return;
    const offset = generated % POLY_WINDOW;
    window.set(ring.subarray(offset));
    window.set(ring.subarray(0, offset), POLY_WINDOW - offset);
    const end = (generated / POLY_SAMPLE_RATE) * 1000;
    onsets.analyze(window.subarray(POLY_WINDOW - FAST_WINDOW), end);
    // Timing can use the zero-padded attack; pitch selection still waits for
    // its complete short window, independently of this envelope history.
    if (generated < FAST_WINDOW) return;
    const single = fast.analyze(window.subarray(POLY_WINDOW - FAST_WINDOW));
    if (
      levels.length === 3 &&
      fast.level > levels[0] * 1.35 &&
      fast.level > levels[2] * 1.08
    )
      attack = end;
    levels.push(fast.level);
    if (levels.length > 3) levels.shift();
    const polyActive = active.size > 1;
    // A two-note interval does not need the long chord window or a third
    // pitch class. Both roots must be present and must not be overtones.
    if (
      generated >= INTERVAL_WINDOW &&
      active.size <= 2 &&
      end - (soundStart ?? 0) >= (INTERVAL_WINDOW / POLY_SAMPLE_RATE) * 1000 &&
      ((!single && (polyActive || end - monoSeen > 120)) ||
        (single &&
          single.midi === monoPitch &&
          end - monoChanged >= (INTERVAL_WINDOW / POLY_SAMPLE_RATE) * 1000))
    ) {
      const pitches = interval(window.subarray(POLY_WINDOW - INTERVAL_WINDOW));
      const roots = pitches.filter(
        pitch =>
          interval.hasFundamental(pitch.midi) &&
          (monoPitch === undefined || !isHarmonic(pitch.midi, monoPitch)) &&
          !pitches.some(lower => isHarmonic(pitch.midi, lower.midi)),
      );
      if (roots.length === 2) {
        update(
          roots.map(pitch => noteName(pitch.midi)),
          end - (INTERVAL_WINDOW / 2 / POLY_SAMPLE_RATE) * 1000,
          end,
          undefined,
          2,
        );
        return;
      }
    }
    if (single && !polyActive) {
      if (monoPitch !== single.midi) {
        monoPitch = single.midi;
        monoChanged = end;
        detect.reset();
        interval.reset();
        confidence.reset();
      }
      monoSeen = end;
    }
    const windowDuration = (POLY_WINDOW / POLY_SAMPLE_RATE) * 1000;
    const polyReady =
      generated >= POLY_WINDOW &&
      end - (soundStart ?? 0) >= windowDuration &&
      end - monoChanged >= windowDuration;
    if (!polyActive && single) {
      const confirmed = polyReady
        ? confidence.filter(detect(window))
        : undefined;
      let pitches = confirmed?.pitches ?? [];
      pitches = filterHarmonics(pitches, end - attack <= windowDuration);
      const primary = pitches.find(pitch => pitch.midi === single.midi);
      if (
        !primary ||
        !pitches.some(
          pitch =>
            pitch.midi !== single.midi &&
            pitch.strength >= primary.strength * 0.6,
        )
      )
        pitches = [single];
      update(
        pitches.map(pitch => noteName(pitch.midi)),
        end - (FAST_WINDOW / 2 / POLY_SAMPLE_RATE) * 1000,
        end,
        undefined,
        pitches.length === 1 ? 2 : confirmed?.frames,
        [],
        // A preceding semitone can excite this short band. Only a fresh
        // attack can timestamp a fast solo change, not an old nearby pitch.
        pitches.length === 1 ? 160 : 640,
      );
      return;
    }
    // Do not fit the old and new solo notes as a chord during a brief change
    // or pick transient. Their times still come from the audio sample clock.
    if (!polyActive && end - monoSeen <= 120) return;
    if (!polyReady) return;
    const confirmed = confidence.filter(detect(window));
    const pitches = filterHarmonics(confirmed.pitches, false);
    const strongest = Math.max(0, ...pitches.map(pitch => pitch.strength));
    // During an existing chord, a new voice needs stronger onset evidence.
    // This rejects short residual partials when another voice is released.
    const notes = pitches
      .filter(pitch => {
        const note = noteName(pitch.midi);
        const lower = pitches.find(other => other.midi === pitch.midi - 12);
        const weakNewOctave =
          lower &&
          active.has(noteName(lower.midi)) &&
          pitch.strength < lower.strength * 0.6;
        const separatePick =
          onsets.get(pitch.midi, end)?.independent &&
          !Array.from(active.keys()).some(note =>
            isHarmonic(pitch.midi, midiNumber(note)),
          );
        return (
          !active.size ||
          active.has(note) ||
          (!weakNewOctave &&
            (candidates.has(note) ||
              pitch.strength >= strongest * 0.32 ||
              separatePick))
        );
      })
      .map(pitch => noteName(pitch.midi));
    const cautious = pitches
      .filter(pitch => pitch.strength < strongest * 0.5)
      .map(pitch => noteName(pitch.midi));
    update(
      notes,
      end - (POLY_WINDOW / 2 / POLY_SAMPLE_RATE) * 1000,
      end,
      undefined,
      confirmed.frames,
      cautious,
    );
  };
  return {
    get noteCount() {
      return nextId;
    },
    push(chunk: GuitarSamples) {
      if (
        finished ||
        !Number.isFinite(chunk.sampleRate) ||
        chunk.sampleRate <= 0
      )
        return;
      if (!rate) {
        rate = chunk.sampleRate;
        epoch = chunk.startedAt;
        filter1 = lowPass(rate, 0.5411961);
        filter2 = lowPass(rate, 1.306563);
      }
      if (chunk.sampleRate !== rate) return;
      for (let i = 0; i < chunk.samples.length; i++) {
        const current = filter2(filter1(chunk.samples[i]));
        while (nextSample <= received) {
          const fraction = received
            ? Math.max(0, Math.min(1, nextSample - received + 1))
            : 1;
          append(previous + (current - previous) * fraction);
          nextSample += rate / POLY_SAMPLE_RATE;
        }
        previous = current;
        received++;
      }
    },
    finish() {
      if (finished) return;
      finished = true;
      const end = quietStart ?? (received / rate) * 1000;
      const events = Array.from(active, ([note, voice]) =>
        event(note, { ...voice, end: voice.missing ?? end }),
      );
      active.clear();
      candidates.clear();
      released.clear();
      onFrame({ events, soundingNotes: [], noteCount: nextId });
    },
    dispose() {
      finished = true;
      active.clear();
      candidates.clear();
      released.clear();
    },
  };
};
